package com.wanyuecity.energy.operation;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.sql.Date;import java.time.LocalDate;import java.time.LocalDateTime;import java.time.LocalTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class OperationPropertyInspectionService{
 private final JdbcTemplate jdbc;private final ObjectMapper json;public OperationPropertyInspectionService(JdbcTemplate j,ObjectMapper o){jdbc=j;json=o;}
 public List<Map<String,Object>>templates(){return jdbc.queryForList("SELECT t.id,t.name,t.business_type businessType,COALESCE(d.item_label,CASE WHEN t.business_type='DEFAULT' THEN '通用模板' ELSE t.business_type END) businessTypeLabel,t.version_no versionNo,t.fields_json fieldsJson,t.enabled,t.remark,t.updated_at updatedAt FROM operation_property_inspection_template t LEFT JOIN business_dictionary d ON d.dict_type='BUSINESS_TYPE' AND d.item_value=t.business_type ORDER BY t.business_type,t.version_no DESC");}
 public Map<String,Object>resolve(String token){Map<String,Object>s=one("SELECT business_type businessType FROM stall WHERE operation_qr_token=?",token);String type=Objects.toString(s.get("businessType"),"");List<Map<String,Object>>r=jdbc.queryForList("SELECT id,name,business_type businessType,version_no versionNo,fields_json fieldsJson FROM operation_property_inspection_template WHERE enabled=1 AND business_type IN(?,'DEFAULT') ORDER BY CASE WHEN business_type=? THEN 0 ELSE 1 END,version_no DESC LIMIT 1",type,type);if(r.isEmpty())throw bad("未配置物业检查模板");Map<String,Object>m=new LinkedHashMap<>(r.get(0));m.put("fields",parse(m.remove("fieldsJson")));return m;}
 @Transactional public Map<String,Object>saveTemplate(Map<String,Object>b,String user){String name=text(b,"name"),type=text(b,"businessType").toUpperCase(Locale.ROOT);if(name.isBlank())throw bad("模板名称不能为空");if(type.isBlank())type="DEFAULT";List<Map<String,Object>>fields=b.get("fields")instanceof List<?>l?l.stream().filter(Map.class::isInstance).map(x->(Map<String,Object>)x).toList():List.of();if(fields.isEmpty())throw bad("至少配置一个检查题");Set<String>codes=new HashSet<>();for(Map<String,Object>f:fields){String code=Objects.toString(f.get("code"),"").trim(),label=Objects.toString(f.get("label"),"").trim(),fieldType=Objects.toString(f.get("type"),"BOOLEAN").toUpperCase(Locale.ROOT);if(!code.matches("[A-Za-z][A-Za-z0-9_]{0,40}")||label.isBlank())throw bad("题目编码或标题不正确");if(!codes.add(code))throw bad("题目编码不能重复");if(!Set.of("BOOLEAN","TEXT","NUMBER","IMAGE").contains(fieldType))throw bad("不支持的题目类型");f.put("code",code);f.put("label",label);f.put("type",fieldType);}Integer v=jdbc.queryForObject("SELECT COALESCE(MAX(version_no),0)+1 FROM operation_property_inspection_template WHERE business_type=?",Integer.class,type);jdbc.update("UPDATE operation_property_inspection_template SET enabled=0 WHERE business_type=?",type);jdbc.update("INSERT INTO operation_property_inspection_template(name,business_type,version_no,fields_json,enabled,created_by) VALUES(?,?,?,?,1,?)",name,type,v,toJson(fields),user);return Map.of("businessType",type,"versionNo",v);}
 @Transactional public void enableTemplate(Long id){Map<String,Object>t=one("SELECT business_type businessType FROM operation_property_inspection_template WHERE id=?",id);jdbc.update("UPDATE operation_property_inspection_template SET enabled=0 WHERE business_type=?",t.get("businessType"));jdbc.update("UPDATE operation_property_inspection_template SET enabled=1 WHERE id=?",id);}
 @Transactional public Map<String,Object>submit(String token,Map<String,Object>b,String username){Map<String,Object>s=one("SELECT s.id,s.status,s.business_type businessType,COALESCE(NULLIF(m.merchant_name,''),s.stall_name) merchantName FROM stall s LEFT JOIN merchant m ON m.id=s.current_merchant_id WHERE s.operation_qr_token=?",token);if(!"OCCUPIED".equals(s.get("status"))||"CK".equalsIgnoreCase(Objects.toString(s.get("businessType"),"")))throw bad("该铺位不在物业日清检查范围");Map<String,Object>t=resolve(token);Map<String,Object>a=b.get("answers")instanceof Map<?,?>m?(Map<String,Object>)m:new HashMap<>();boolean normal=true;for(Map<String,Object>f:(List<Map<String,Object>>)t.get("fields")){String code=Objects.toString(f.get("code")),label=Objects.toString(f.get("label"));Object val=a.get(code);if(Boolean.TRUE.equals(f.get("required"))&&(val==null||val.toString().isBlank()))throw bad("请填写："+label);if("BOOLEAN".equals(f.get("type"))&&f.containsKey("expected")&&Boolean.parseBoolean(Objects.toString(val,"false"))!=Boolean.parseBoolean(Objects.toString(f.get("expected"))))normal=false;}String desc=Objects.toString(a.get("exceptionDescription"),"").trim();if(!normal&&desc.isBlank())throw bad("发现异常时请填写异常说明");Map<String,Object>u=one("SELECT id,COALESCE(NULLIF(display_name,''),username) displayName FROM sys_user WHERE username=?",username);LocalDate d=inspectionPeriodDate();List<Map<String,Object>>c=jdbc.queryForList("SELECT id FROM operation_clearance_record WHERE stall_id=? AND period_date=?",s.get("id"),Date.valueOf(d));Object cid=c.isEmpty()?null:c.get(0).get("id");String no="PI"+d.format(DateTimeFormatter.BASIC_ISO_DATE)+"-"+s.get("id");jdbc.update("INSERT INTO operation_property_inspection(inspection_no,stall_id,period_date,clearance_record_id,template_id,template_version,template_name_snapshot,answers_json,inspector_user_id,inspector_name,merchant_name_snapshot,status,exception_description) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE clearance_record_id=VALUES(clearance_record_id),template_id=VALUES(template_id),template_version=VALUES(template_version),template_name_snapshot=VALUES(template_name_snapshot),answers_json=VALUES(answers_json),inspector_user_id=VALUES(inspector_user_id),inspector_name=VALUES(inspector_name),status=VALUES(status),exception_description=VALUES(exception_description),inspected_at=CURRENT_TIMESTAMP(3)",no,s.get("id"),Date.valueOf(d),cid,t.get("id"),t.get("versionNo"),t.get("name"),toJson(a),u.get("id"),u.get("displayName"),s.get("merchantName"),normal?"NORMAL":"ABNORMAL",desc);return one("SELECT id,inspection_no inspectionNo,status,inspected_at inspectedAt FROM operation_property_inspection WHERE stall_id=? AND period_date=?",s.get("id"),Date.valueOf(d));}
 public List<Map<String,Object>>records(String date){return jdbc.queryForList("SELECT i.id,i.period_date periodDate,s.stall_code stallCode,i.merchant_name_snapshot merchantName,i.inspector_name inspectorName,i.template_name_snapshot templateName,i.status,i.exception_description exceptionDescription,i.inspected_at inspectedAt,i.clearance_record_id clearanceRecordId FROM operation_property_inspection i JOIN stall s ON s.id=i.stall_id WHERE (?='' OR i.period_date=?) ORDER BY i.period_date DESC,i.inspected_at DESC LIMIT 1000",date,date.isBlank()?null:Date.valueOf(date));}
 private LocalDate inspectionPeriodDate(){LocalDateTime now=LocalDateTime.now();return now.toLocalTime().isBefore(LocalTime.of(9,0))?now.toLocalDate().minusDays(1):now.toLocalDate();}private List<Map<String,Object>>parse(Object v){try{return json.readValue(Objects.toString(v,"[]"),new TypeReference<>(){});}catch(Exception e){throw bad("模板解析失败");}}private String toJson(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw bad("数据保存失败");}}private String text(Map<String,Object>b,String k){return Objects.toString(b.get(k),"").trim();}private Map<String,Object>one(String q,Object...a){List<Map<String,Object>>r=jdbc.queryForList(q,a);if(r.isEmpty())throw bad("数据不存在");return r.get(0);}private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
